/*
 * ring_$copy_to_user - scatter a received buffer into the caller's I/O vector
 *
 * Original address: 0x00E77382 (module-local; the SAU2 map has no symbol
 * here; was Ghidra ring_$copy_to_user)
 * Size: 128 bytes (0x00E77382 .. 0x00E77401)
 * Generated by: Claude Opus 5.5
 *
 * RING_$SVC_READ calls it twice with the same iov cursor (index word at
 * (-0x7e,A6) seeded 1, offset word at (-0x7c,A6) seeded 0): once for the
 * header bytes after the 0x1C-byte ring header (0x00E775D6), once for the
 * data buffer (0x00E77634).
 *
 * Frame (link.w A6,-0x10): (0x8,A6) src_va (A0, read once into D4),
 * (0xc,A6) len (D3w), (0xe,A6) iov (A2), (0x12,A6) iov_max (D5w),
 * (0x14,A6) iov_index (A3), (0x18,A6) iov_offset (A4); (-0x8,A6) the
 * destination VA.
 *
 * Blocks:
 *   0x00E7739E-0x00E773A6  D4 = *src_va; D3 = len; bra to the test
 *   0x00E773A8-0x00E773CC  dest = iov[i].va + offset; n = iov[i].len
 *                          (zero-extended) - offset, capped at D3 (signed
 *                          `cmp.l` / `ble`)
 *   0x00E773CC-0x00E773DE  OS_$DATA_COPY(D4, dest, n)
 *   0x00E773E2-0x00E773EE  D4 += n; D3 -= n; D3 != 0 -> offset = 0, index++;
 *                          D3 == 0 -> offset = n (not offset + n: an element
 *                          left part-filled is resumed at n by the next call)
 *   0x00E773F0-0x00E773F6  loop while D3 != 0 && *iov_index <= iov_max
 *                          (signed `bge`)
 */

#include "ring/ring_internal.h"

void ring_$copy_to_user(uint32_t *src_va, int16_t len, ring_$iov_t *iov,
                        int16_t iov_max, int16_t *iov_index,
                        int16_t *iov_offset)
{
    uint32_t src;           /* D4 */
    int16_t remaining;      /* D3w */
    int32_t offset;         /* D1 */
    ring_$iov_t *elem;
    uint32_t dest;          /* (-0x8,A6) */
    int32_t n;              /* D2 */
    int32_t n_copy;         /* D6 */

    /* 0x00E7739E-0x00E773A4 */
    src = *src_va;
    remaining = len;

    /* 0x00E773F2-0x00E773F6, entered from the bra at 0x00E773A6 */
    while (remaining != 0 && iov_max >= *iov_index) {
        /* 0x00E773A8-0x00E773B6: Pascal [1..n], element i at iov + 8*(i-1) */
        offset = (int32_t)*iov_offset;
        elem = &iov[*iov_index - 1];
        dest = elem->va + (uint32_t)offset;

        /* 0x00E773BA-0x00E773CA */
        n = (int32_t)elem->len - offset;
        if (n > (int32_t)remaining) {
            n = (int32_t)remaining;
        }

        /* 0x00E773CC-0x00E773DE: the copy length is the low word, extended */
        n_copy = (int32_t)(int16_t)n;
        OS_$DATA_COPY(ARCH_VA_TO_PTR(src), ARCH_VA_TO_PTR(dest),
                      (uint32_t)n_copy);

        /* 0x00E773E2-0x00E773EE */
        src += (uint32_t)n_copy;
        remaining = (int16_t)(remaining - (int16_t)n);
        if (remaining == 0) {
            *iov_offset = (int16_t)n;       /* 0x00E773E8 */
        } else {
            *iov_offset = 0;                /* 0x00E773EC */
            (*iov_index)++;
        }
    }
}
